import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"49、【革】 離下兌上","description":"周易口訣義 - 49、【革】 離下兌上","frontmatter":{"title":"49、【革】 離下兌上","description":"周易口訣義 - 49、【革】 離下兌上"},"headers":[],"relativePath":"classics/koujueyi/051.md","filePath":"classics/koujueyi/051.md"}'),r={name:"classics/koujueyi/051.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_49、【革】-離下兌上" tabindex="-1">49、【革】 離下兌上 <a class="header-anchor" href="#_49、【革】-離下兌上" aria-label="Permalink to “49、【革】 離下兌上”">​</a></h1><p>彖曰：革，水火相息，二女同居，其志不相得，曰「革」。「巳日乃孚」，革而信之。文明以說，大亨以正，革而當，其悔乃亡。天地革而四時成，湯武革命，順乎天而應乎人，革之時大矣哉！</p><p>象曰：澤中有火，革。君子以治歷明時。</p><p>初九：鞏用黃牛之革。</p><p>象曰：「鞏用黃牛」，不可以有為也。</p><p>六二：巳日乃革之，徵吉，無咎。</p><p>象曰：「巳日革之」，行有嘉也。</p><p>九三：徵兇，貞厲。革言三就，有孚。</p><p>象曰：「革言三就」，又何之矣。</p><p>九四，悔亡，有孚，改命吉。</p><p>象曰：改命之「吉」，信志也。</p><p>九五，大人虎變，未佔有孚。</p><p>象曰：「大人虎變」，其文炳也。</p><p>上六，君子豹變，小人革面，徵兇，居貞吉。</p><p>象曰：「君子豹變」，其文蔚也；「小人革面」，順以從君也。</p><p>解讀</p><p>「革巳日乃孚」者，革，改變之名，易舊之義，故名「革」也。革既改舊易新，即是王者創制命令，改前王之法度。以其初施法令，民有所感，未便從伏，必須已竟今日，明日方始從令。故宋衷雲：人性習常，不說改易，及變之後，樂其所成，故即日不孚，巳日乃孚矣，故曰「巳日乃孚」也。已，竟也。「元亨利貞，悔亡」者，悔之所生，生乎變動也。今革既變，故人心不安，必有憂悔。今革道既當，即得大通利正，而憂悔乃亡，故須備此四德矣。象曰「澤中有火，革」者，火居澤下，火炎上，澤潤下，二性交，故能變革也。「君子以治歷明時」者，寒暑迭終，日月更運，天時人事，各以時遷，故君子觀茲革象，修治歷數，以明天時也。</p><p>「初九，鞏用黃牛之革」者，鞏，固也；黃，中也；革是牛皮，生曰革，熟曰韋。今初九處革之初，未肯從變，言其執志堅固，守中和之道，不肯造次從變，如似牛皮堅韌，不從改變之命也。</p><p>「六二，巳日乃革之，徵吉，無咎」者，陰柔之體，不敢為先，故革命已行，竟日之後，乃始從之，故曰「巳日乃革之」。既從革命，無復疑阻，往就於五，不被疑難，故可以徵進而獲無咎也。</p><p>「九三，徵兇，貞厲，革言三就，有孚」者，三處炎極，火性上炎，上體是水，水性柔順，九三以剛居火極，火性剛猛，故有革命之言。而上體三爻，以受命令，不敢有違，其言不虛，故曰「革言三就，有孚」也。人既從命，更興征伐，即是非理興師，所以致兇。夫興師動眾，是正道之危，故曰「徵兇，貞厲」也。</p><p>「九四，悔亡，有孚改命，吉」者，無應，故有憂悔，能從革命，故曰「悔亡」也。居水火之際，不為固吝，信彼改命之制，合時之願，所以獲吉，故曰「有孚，改命，吉」也。</p><p>「九五：大人虎變，未佔有孚」者，居得尊位，以大人之德為革之主，即是革去前王之命，為新創之君，信德自著，合人之心，不勞佔決，斯湯武之君是也。「虎變」者，謂改正朔，易服色，取其文章炳煥，又取虎之威猛可畏之義也。</p><p>「上六：君子豹變，小人革面，徵兇，居貞吉」者，處革之極，變道已成，君子居之，雖不如大人之變，如虎之文，然亦可順時而行，如豹文之映蔚，故曰「君子豹變」也。若小人處之，但能變其顏面，順上而已，故曰「小人革面」也。革變已極，人皆從命，固宜靜處，而更以征伐為求，即是躁擾於人，所以致兇。如靜而居之，皆獲吉，故曰「徵兇，居貞吉」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
